import { strict as assert } from 'assert';
import {
  handleCancelWorkspaceDeployment,
  handleCreateWorkspaceDeployment,
  handleGetWorkspaceDeployment,
  handleGetWorkspaceDeploymentEvents,
} from './workspace-deployments.js';

function createWorkspaceDeploymentApiEnv(): { env: Record<string, unknown>; state: { deploymentExists: boolean } } {
  const state = {
    deploymentExists: false,
  };

  const env = {
    WORKSPACE_DEPLOY_ENABLED: 'true',
    DB: {
      prepare(sql: string) {
        if (/SELECT key, value FROM runtime_flags/i.test(sql)) {
          return {
            async all() {
              return { results: [] };
            },
          };
        }

        if (/SELECT \* FROM workspaces WHERE id = \?/i.test(sql)) {
          return {
            bind() {
              return {
                async first<T>() {
                  return {
                    id: 'ws_abc12345',
                    status: 'ready',
                    source_type: 'checkpoint',
                    checkpoint_id: null,
                    commit_sha: 'a'.repeat(40),
                    source_ref: 'main',
                    source_project_root: '.',
                    source_bundle_key: 'key',
                    source_bundle_sha256: 'f'.repeat(64),
                    source_bundle_bytes: 1,
                    sandbox_id: 'workspace-ws_abc12345',
                    baseline_ready: 1,
                    error_code: null,
                    error_message: null,
                    last_deployment_id: null,
                    last_deployment_status: null,
                    last_deployed_url: null,
                    last_deployed_at: null,
                    last_deployment_error_code: null,
                    last_deployment_error_message: null,
                    last_event_seq: 0,
                    created_at: '2026-03-08T00:00:00.000Z',
                    updated_at: '2026-03-08T00:00:00.000Z',
                    deleted_at: null,
                  } as T;
                },
              };
            },
          };
        }

        if (/SELECT deployment_id, request_payload_sha256, expires_at/i.test(sql)) {
          return {
            bind() {
              return {
                async first<T>() {
                  return null as T;
                },
              };
            },
          };
        }

        if (/INSERT INTO workspace_deployments/i.test(sql)) {
          return {
            bind(...values: unknown[]) {
              return {
                async first<T>() {
                  state.deploymentExists = true;
                  return {
                    id: values[0],
                    workspace_id: values[1],
                    status: 'queued',
                    provider: values[2],
                    idempotency_key: values[3],
                    request_payload_json: values[4],
                    request_payload_sha256: values[5],
                    max_retries: values[6],
                    attempt_count: 0,
                    source_snapshot_sha256: null,
                    source_bundle_key: null,
                    provenance_json: values[7],
                    provider_deployment_id: null,
                    deployed_url: null,
                    last_event_seq: 0,
                    cancel_requested_at: null,
                    started_at: null,
                    finished_at: null,
                    duration_ms: null,
                    result_json: null,
                    error_code: null,
                    error_message: null,
                    created_at: '2026-03-08T00:00:00.000Z',
                    updated_at: '2026-03-08T00:00:00.000Z',
                  } as T;
                },
              };
            },
          };
        }

        if (/INSERT INTO workspace_deployment_idempotency/i.test(sql)) {
          return {
            bind() {
              return {
                async run() {
                  return { success: true, meta: { changes: 1 } };
                },
              };
            },
          };
        }

        if (/UPDATE workspace_deployments SET last_event_seq = last_event_seq \+ 1/i.test(sql)) {
          return {
            bind() {
              return {
                async first<T>() {
                  return { last_event_seq: 1 } as T;
                },
              };
            },
          };
        }

        if (/INSERT INTO workspace_deployment_events/i.test(sql)) {
          return {
            bind() {
              return {
                async run() {
                  return { success: true, meta: { changes: 1 } };
                },
              };
            },
          };
        }

        if (/SELECT 1\s+FROM workspace_deployment_events/i.test(sql)) {
          return {
            bind() {
              return {
                async first<T>() {
                  return null as T;
                },
              };
            },
          };
        }

        if (/SELECT \* FROM workspace_deployments WHERE id = \? AND workspace_id = \?/i.test(sql)) {
          return {
            bind(deploymentId: string) {
              return {
                async first<T>() {
                  if (!state.deploymentExists) {
                    return null as T;
                  }
                  return {
                    id: deploymentId,
                    workspace_id: 'ws_abc12345',
                    status: 'queued',
                    provider: 'simulated',
                    idempotency_key: 'idem-1',
                    request_payload_json: '{}',
                    request_payload_sha256: 'hash',
                    max_retries: 2,
                    attempt_count: 0,
                    source_snapshot_sha256: null,
                    source_bundle_key: null,
                    provenance_json: '{}',
                    provider_deployment_id: null,
                    deployed_url: null,
                    last_event_seq: 1,
                    cancel_requested_at: null,
                    started_at: null,
                    finished_at: null,
                    duration_ms: null,
                    result_json: null,
                    error_code: null,
                    error_message: null,
                    created_at: '2026-03-08T00:00:00.000Z',
                    updated_at: '2026-03-08T00:00:00.000Z',
                  } as T;
                },
              };
            },
          };
        }

        if (/SELECT seq, event_type, payload_json, created_at/i.test(sql)) {
          return {
            bind() {
              return {
                async all<T>() {
                  return {
                    results: [
                      {
                        seq: 1,
                        event_type: 'deployment_created',
                        payload_json: '{"ok":true}',
                        created_at: '2026-03-08T00:00:00.000Z',
                      },
                    ],
                  } as unknown as T;
                },
              };
            },
          };
        }

        if (/UPDATE workspace_deployments\s+SET cancel_requested_at/i.test(sql)) {
          return {
            bind() {
              return {
                async run() {
                  return { success: true, meta: { changes: 1 } };
                },
              };
            },
          };
        }

        if (/UPDATE workspace_deployments\s+SET status = 'cancelled'/i.test(sql)) {
          return {
            bind() {
              return {
                async run() {
                  return { success: true, meta: { changes: 0 } };
                },
              };
            },
          };
        }

        if (/UPDATE workspaces SET/i.test(sql)) {
          return {
            bind() {
              return {
                async run() {
                  return { success: true, meta: { changes: 1 } };
                },
              };
            },
          };
        }

        return {
          bind() {
            return {
              async first() {
                return null;
              },
              async all() {
                return { results: [] };
              },
              async run() {
                return { success: true, meta: { changes: 1 } };
              },
            };
          },
        };
      },
    },
  };

  return { env, state };
}

export async function runWorkspaceDeploymentApiTests(): Promise<void> {
  const ctx = {
    waitUntil() {
      // no-op for tests
    },
  } as unknown as ExecutionContext;

  {
    const { env } = createWorkspaceDeploymentApiEnv();
    const request = new Request('https://example.com/api/workspaces/ws_abc12345/deploy', {
      method: 'POST',
      body: JSON.stringify({ provider: 'simulated' }),
      headers: { 'Content-Type': 'application/json' },
    });
    const response = await handleCreateWorkspaceDeployment('ws_abc12345', request, env as never, ctx);
    assert.equal(response.status, 400);
  }

  {
    const { env, state } = createWorkspaceDeploymentApiEnv();
    const request = new Request('https://example.com/api/workspaces/ws_abc12345/deploy', {
      method: 'POST',
      body: JSON.stringify({ provider: 'simulated' }),
      headers: { 'Content-Type': 'application/json', 'Idempotency-Key': 'idem-1' },
    });
    const response = await handleCreateWorkspaceDeployment('ws_abc12345', request, env as never, ctx);
    assert.equal(response.status, 202);
    assert.equal(state.deploymentExists, true);
  }

  {
    const { env } = createWorkspaceDeploymentApiEnv();
    const request = new Request('https://example.com/api/workspaces/ws_abc12345/deploy', {
      method: 'POST',
      body: JSON.stringify({ provider: 'vercel' }),
      headers: { 'Content-Type': 'application/json', 'Idempotency-Key': 'idem-unsupported' },
    });
    const response = await handleCreateWorkspaceDeployment('ws_abc12345', request, env as never, ctx);
    assert.equal(response.status, 400);
  }

  {
    const { env, state } = createWorkspaceDeploymentApiEnv();
    state.deploymentExists = true;
    const response = await handleGetWorkspaceDeployment('ws_abc12345', 'dep_abcd1234', env as never);
    assert.equal(response.status, 200);
  }

  {
    const { env, state } = createWorkspaceDeploymentApiEnv();
    state.deploymentExists = true;
    const request = new Request('https://example.com/api/workspaces/ws_abc12345/deployments/dep_abcd1234/events?from=0');
    const response = await handleGetWorkspaceDeploymentEvents('ws_abc12345', 'dep_abcd1234', request, env as never);
    assert.equal(response.status, 200);
  }

  {
    const { env, state } = createWorkspaceDeploymentApiEnv();
    state.deploymentExists = true;
    const response = await handleCancelWorkspaceDeployment('ws_abc12345', 'dep_abcd1234', env as never);
    assert.equal(response.status, 202);
  }
}

import type { Env } from '../types.js';
import { loadRuntimeFlags } from '../lib/flags.js';
import {
  appendWorkspaceDeploymentEvent,
  createWorkspaceDeployment,
  generateWorkspaceDeploymentId,
  getWorkspace,
  getWorkspaceDeployment,
  hasWorkspaceDeploymentEvent,
  listWorkspaceDeploymentEvents,
  WorkspaceDeploymentIdempotencyConflictError,
} from '../lib/db.js';
import { createWorkspaceDeploymentQueueMessage } from '../lib/workspace-deployment-queue.js';
import { cancelWorkspaceDeployment, runWorkspaceDeploymentInlineWithRetries } from '../lib/workspace-deployment-runner.js';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, DELETE, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Idempotency-Key',
};

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json', ...corsHeaders },
  });
}

function parseInteger(input: unknown, fallback: number, min: number, max: number): number {
  if (typeof input !== 'number' || !Number.isFinite(input)) {
    return fallback;
  }
  const value = Math.floor(input);
  if (value < min) {
    return min;
  }
  if (value > max) {
    return max;
  }
  return value;
}

function parseBoolean(input: unknown, fallback: boolean): boolean {
  if (typeof input !== 'boolean') {
    return fallback;
  }
  return input;
}

async function sha256Hex(input: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(input));
  return Array.from(new Uint8Array(digest))
    .map((byte) => byte.toString(16).padStart(2, '0'))
    .join('');
}

async function ensureWorkspaceReady(env: Env, workspaceId: string): Promise<Response | null> {
  const workspace = await getWorkspace(env.DB, workspaceId);
  if (!workspace) {
    return jsonResponse({ error: 'Workspace not found' }, 404);
  }
  if (workspace.status !== 'ready') {
    return jsonResponse(
      {
        error: 'Workspace is not ready',
        workspace: {
          id: workspace.id,
          status: workspace.status,
          errorCode: workspace.errorCode,
          errorMessage: workspace.errorMessage,
        },
      },
      409
    );
  }
  return null;
}

async function ensureWorkspaceExists(env: Env, workspaceId: string): Promise<Response | null> {
  const workspace = await getWorkspace(env.DB, workspaceId);
  if (!workspace) {
    return jsonResponse({ error: 'Workspace not found' }, 404);
  }
  return null;
}

async function ensureWorkspaceDeployEnabled(env: Env): Promise<Response | null> {
  const flags = await loadRuntimeFlags(env);
  if (!flags.workspaceDeployEnabled) {
    return jsonResponse(
      {
        error: 'Workspace deploy is disabled',
        code: 'workspace_deploy_disabled',
      },
      403
    );
  }
  return null;
}

export async function handleCreateWorkspaceDeployment(
  workspaceId: string,
  request: Request,
  env: Env,
  ctx?: ExecutionContext
): Promise<Response> {
  try {
    const enabled = await ensureWorkspaceDeployEnabled(env);
    if (enabled) {
      return enabled;
    }

    const workspaceCheck = await ensureWorkspaceReady(env, workspaceId);
    if (workspaceCheck) {
      return workspaceCheck;
    }

    if (!env.WORKSPACE_DEPLOYS_QUEUE && !ctx) {
      return jsonResponse(
        {
          error: 'Workspace deployment runner is unavailable',
          code: 'workspace_deploy_runner_unavailable',
        },
        503
      );
    }

    const idempotencyKey = (request.headers.get('Idempotency-Key') ?? '').trim();
    if (!idempotencyKey) {
      return jsonResponse({ error: 'Missing required Idempotency-Key header' }, 400);
    }

    const payloadRaw = await request.text();
    let payload: Record<string, unknown> = {};
    if (payloadRaw.trim()) {
      const parsed = JSON.parse(payloadRaw) as unknown;
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        return jsonResponse({ error: 'Request body must be a JSON object' }, 400);
      }
      payload = parsed as Record<string, unknown>;
    }

    const provider = typeof payload.provider === 'string' && payload.provider.trim() ? payload.provider.trim() : 'simulated';
    if (provider !== 'simulated') {
      return jsonResponse(
        {
          error: 'Unsupported deployment provider',
          code: 'unsupported_deploy_provider',
          allowedProviders: ['simulated'],
        },
        400
      );
    }
    const retry =
      payload.retry && typeof payload.retry === 'object' && !Array.isArray(payload.retry)
        ? (payload.retry as Record<string, unknown>)
        : {};
    const validation =
      payload.validation && typeof payload.validation === 'object' && !Array.isArray(payload.validation)
        ? (payload.validation as Record<string, unknown>)
        : {};
    const provenance =
      payload.provenance && typeof payload.provenance === 'object' && !Array.isArray(payload.provenance)
        ? (payload.provenance as Record<string, unknown>)
        : {};
    const maxRetries = parseInteger(retry.maxRetries, 2, 0, 5);

    const requestPayload = {
      provider,
      retry: {
        maxRetries,
      },
      validation: {
        runBuildIfPresent: parseBoolean(validation.runBuildIfPresent, true),
        runTestsIfPresent: parseBoolean(validation.runTestsIfPresent, true),
      },
      rollbackOnFailure: parseBoolean(payload.rollbackOnFailure, true),
      provenance: {
        trigger: typeof provenance.trigger === 'string' && provenance.trigger.trim() ? provenance.trigger.trim() : 'manual',
        taskId: typeof provenance.taskId === 'string' && provenance.taskId.trim() ? provenance.taskId.trim() : null,
        operationId:
          typeof provenance.operationId === 'string' && provenance.operationId.trim() ? provenance.operationId.trim() : null,
        note: typeof provenance.note === 'string' && provenance.note.trim() ? provenance.note.trim() : null,
      },
    };

    const requestPayloadSha256 = await sha256Hex(JSON.stringify(requestPayload));
    const created = await createWorkspaceDeployment(env.DB, {
      id: generateWorkspaceDeploymentId(),
      workspaceId,
      provider,
      idempotencyKey,
      requestPayload,
      requestPayloadSha256,
      maxRetries,
      provenance: requestPayload.provenance,
    });

    if (!created.reused) {
      await appendWorkspaceDeploymentEvent(env.DB, {
        workspaceId,
        deploymentId: created.deployment.id,
        eventType: 'deployment_created',
        payload: {
          provider,
          maxRetries,
          provenance: requestPayload.provenance,
        },
      });
    }

    if (created.deployment.status === 'queued') {
      const hasEnqueuedEvent = await hasWorkspaceDeploymentEvent(
        env.DB,
        workspaceId,
        created.deployment.id,
        'deployment_enqueued'
      );
      const shouldRecoverQueued =
        created.reused && (created.deployment.error?.code === 'retry_scheduled' || created.deployment.attemptCount > 0);
      if (!hasEnqueuedEvent || shouldRecoverQueued) {
        if (env.WORKSPACE_DEPLOYS_QUEUE) {
          await env.WORKSPACE_DEPLOYS_QUEUE.send(
            createWorkspaceDeploymentQueueMessage(workspaceId, created.deployment.id)
          );
        } else if (ctx) {
          ctx.waitUntil(
            runWorkspaceDeploymentInlineWithRetries(env, workspaceId, created.deployment.id, created.deployment.maxRetries + 1)
          );
        }

        await appendWorkspaceDeploymentEvent(env.DB, {
          workspaceId,
          deploymentId: created.deployment.id,
          eventType: 'deployment_enqueued',
          payload: {
            mode: env.WORKSPACE_DEPLOYS_QUEUE ? 'queue' : 'inline',
            reused: created.reused,
          },
        });
      }
    }

    return jsonResponse({ deployment: created.deployment }, created.reused ? 200 : 202);
  } catch (error) {
    if (error instanceof WorkspaceDeploymentIdempotencyConflictError) {
      return jsonResponse(
        {
          error: 'Idempotency key has already been used with different payload',
          code: 'idempotency_key_conflict',
        },
        409
      );
    }

    if (error instanceof SyntaxError) {
      return jsonResponse({ error: 'Invalid JSON body' }, 400);
    }

    const message = error instanceof Error ? error.message : String(error);
    return jsonResponse({ error: `Failed to create workspace deployment: ${message}` }, 500);
  }
}

export async function handleGetWorkspaceDeployment(
  workspaceId: string,
  deploymentId: string,
  env: Env
): Promise<Response> {
  const workspaceMissing = await ensureWorkspaceExists(env, workspaceId);
  if (workspaceMissing) {
    return workspaceMissing;
  }

  const deployment = await getWorkspaceDeployment(env.DB, workspaceId, deploymentId);
  if (!deployment) {
    return jsonResponse({ error: 'Deployment not found' }, 404);
  }

  return jsonResponse({ deployment });
}

export async function handleGetWorkspaceDeploymentEvents(
  workspaceId: string,
  deploymentId: string,
  request: Request,
  env: Env
): Promise<Response> {
  const workspaceMissing = await ensureWorkspaceExists(env, workspaceId);
  if (workspaceMissing) {
    return workspaceMissing;
  }

  const deployment = await getWorkspaceDeployment(env.DB, workspaceId, deploymentId);
  if (!deployment) {
    return jsonResponse({ error: 'Deployment not found' }, 404);
  }

  const url = new URL(request.url);
  const from = Number.parseInt(url.searchParams.get('from') ?? '0', 10);
  const limit = Number.parseInt(url.searchParams.get('limit') ?? '500', 10);
  const fromExclusive = Number.isFinite(from) && from > 0 ? from : 0;
  const boundedLimit = Number.isFinite(limit) ? Math.max(1, Math.min(limit, 1000)) : 500;

  const events = await listWorkspaceDeploymentEvents(env.DB, workspaceId, deploymentId, fromExclusive, boundedLimit);
  return jsonResponse({ deploymentId, events });
}

export async function handleCancelWorkspaceDeployment(
  workspaceId: string,
  deploymentId: string,
  env: Env
): Promise<Response> {
  const workspaceMissing = await ensureWorkspaceExists(env, workspaceId);
  if (workspaceMissing) {
    return workspaceMissing;
  }

  const cancelResult = await cancelWorkspaceDeployment(env, workspaceId, deploymentId);
  if (!cancelResult.deployment) {
    return jsonResponse({ error: 'Deployment not found' }, 404);
  }

  if (cancelResult.updated) {
    return jsonResponse({ deployment: cancelResult.deployment }, 202);
  }

  if (cancelResult.deployment.status === 'running' && cancelResult.deployment.cancelRequestedAt) {
    return jsonResponse({ deployment: cancelResult.deployment }, 202);
  }

  return jsonResponse(
    {
      error: 'Deployment is already terminal and cannot be cancelled',
      code: 'deployment_not_cancellable',
      deployment: cancelResult.deployment,
    },
    409
  );
}

