import type {
  JobRecord,
  JobResponse,
  JobListItem,
  JobStatus,
  JobPhase,
  WorkspaceRecord,
  WorkspaceResponse,
  WorkspaceStatus,
  WorkspaceOperationRecord,
  WorkspaceOperationResponse,
  WorkspaceOperationType,
