}

export interface CreateWorkspaceTaskInput {
  id: string;
  workspaceId: string;
  prompt: string;
  provider: string;
  model: string;
  idempotencyKey: string;
  requestPayload: unknown;
  requestPayloadSha256: string;
  maxSteps: number;
  maxRetries: number;
  actorId?: string | null;
  toolPolicy?: Record<string, unknown>;
}

export interface CreateWorkspaceDeploymentInput {
  id: string;
  workspaceId: string;
  provider: string;
  idempotencyKey: string;
  requestPayload: unknown;
  requestPayloadSha256: string;
  maxRetries: number;
