+    .first<WorkspaceDeploymentRecord>();
+
+  if (!record) {
+    return null;
+  }
+
+  return toWorkspaceDeploymentResponse(record);
+}
+
+export async function getWorkspaceDeploymentRequestPayload(
+  db: D1Database,
+  deploymentId: string
+): Promise<Record<string, unknown> | null> {
