+    const rollback = await resolveRollbackContext(workspaceId, deploymentId, rollbackOnFailure, env);
+
+    if (deployment?.cancelRequestedAt) {
+      await updateWorkspaceDeploymentStatus(env.DB, deploymentId, 'cancelled', {
+        workspaceId,
