+  for (let cycle = 0; cycle < maxCycles; cycle += 1) {
+    try {
+      await processWorkspaceDeployment(env, workspaceId, deploymentId);
+    } catch {
+      // Retry scheduling is inferred from persisted deployment status.
+    }
