+    const latest = await getWorkspaceDeployment(env.DB, workspaceId, deploymentId);
+    if (!latest) {
+      return;
+    }
+    if (latest.status !== 'queued') {
+      return;
+    }
+    if (latest.error?.code !== 'retry_scheduled') {
+      return;
+    }
+  }
