      provider,
      validation: {
        runBuildIfPresent: parseBoolean(validation.runBuildIfPresent, true),
        runTestsIfPresent: parseBoolean(validation.runTestsIfPresent, true),
      },
      rollbackOnFailure: parseBoolean(payload.rollbackOnFailure, true),
