  sandbox: SandboxClient
): Promise<{ bytes: Uint8Array; sha256: string; objectKeySuffix: string }> {
  const base64 = await runSandboxCommand(
    sandbox,
    `cd ${shellQuote(
      WORKSPACE_ROOT
    )} && tmp_bundle=$(mktemp /tmp/nimbus-workspace-deploy.XXXXXX.tar.gz) && tar -czf "$tmp_bundle" --exclude='.git' . && base64 "$tmp_bundle" && rm -f "$tmp_bundle"`,
    { timeout: 8 * 60 * 1000 }
  );
  const bytes = fromBase64(base64);
  const sha = await sha256Hex(bytes);
  return {
    bytes,
    sha256: sha,
    objectKeySuffix: 'source.tar.gz',
  };
}

