  if (!enabled) {
    return { status: 'disabled' };
  }
  const previous = await getLatestSuccessfulWorkspaceDeployment(env.DB, workspaceId);
  if (!previous || previous.id === deploymentId) {
    return { status: 'no_previous_success' };
  }
  return {
    status: 'retained_previous',
