          return {
            bind() {
              return {
                async run() {
                  if (state.status !== 'queued') {
                    return { success: true, meta: { changes: 0 } };
                  }
                  state.status = 'running';
                  state.attemptCount += 1;
                  if (!state.startedAt) {
                    state.startedAt = '2026-03-08T00:00:00.000Z';
