    ifNotDeleted?: boolean;
  }
): Promise<boolean> {
  const updates: string[] = ['status = ?', 'updated_at = ?'];
  const values: (string | number | null)[] = [status, new Date().toISOString()];

  if (additionalFields) {
    if (additionalFields.baseline_ready !== undefined) {
