  WorkspaceDeploymentResponse,
  WorkspaceDeploymentStatus,
} from '../types.js';

export interface CreateCheckpointJobInput {
  id: string;
  prompt: string;
  checkpointId: string | null;
  commitSha: string;
  sourceRef?: string;
  sourceProjectRoot?: string;
