export async function updateWorkspaceTaskStatus(
  db: D1Database,
  taskId: string,
  status: WorkspaceTaskStatus,
  options?: {
    workspaceId?: string;
    result?: unknown;
    errorCode?: string | null;
    errorMessage?: string | null;
    startedAt?: string | null;
    finishedAt?: string | null;
  }
): Promise<void> {
