          return { stdout: JSON.stringify({ hasBuild: false, hasTest: false }), stderr: '', exitCode: 0 };
        }
        if (command.includes('base64 "$tmp_bundle"')) {
          state.cancelRequestedAt = '2026-03-08T00:00:02.000Z';
