          return { stdout: 'AQID', stderr: '', exitCode: 0 };
        }
        return { stdout: '', stderr: '', exitCode: 0 };
      },
    }));

    await processWorkspaceDeployment(env as never, 'ws_abc12345', 'dep_abcd1234');
