    startedAt: string | null;
    workspaceSummaryUpdateCalls: number;
    workspaceSummaryLastStatus: string | null;
  };
} {
  const state = {
    status: options?.initialStatus ?? 'queued',
    attemptCount: 0,
    events: [] as Array<{ eventType: string; payload: unknown }>,
