): Promise<boolean> {
  const startedAt = new Date().toISOString();
  const result = await db
    .prepare(
      `UPDATE workspace_operations
       SET status = 'running',
           started_at = COALESCE(started_at, ?),
           updated_at = ?
       WHERE id = ? AND workspace_id = ? AND status = 'queued'`
