export async function appendWorkspaceTaskEvent(
  db: D1Database,
  input: {
    workspaceId: string;
    taskId: string;
    eventType: string;
    payload: unknown;
  }
): Promise<number> {
  const seqResult = await db
    .prepare(
      'UPDATE workspace_tasks SET last_event_seq = last_event_seq + 1 WHERE id = ? AND workspace_id = ? RETURNING last_event_seq'
    )
