    const { env, state } = createWorkspaceDeploymentApiEnv();
    state.deploymentExists = true;
    state.deploymentStatus = 'running';
    const response = await handleCancelWorkspaceDeployment('ws_abc12345', 'dep_abcd1234', env as never, ctx);
