export async function getLatestSuccessfulWorkspaceDeployment(
  db: D1Database,
  workspaceId: string
): Promise<WorkspaceDeploymentResponse | null> {
  const record = await db
    .prepare(
      `SELECT *
       FROM workspace_deployments
