  return {
    id: record.id,
    prompt: record.prompt.length > 100 ? record.prompt.slice(0, 100) + '...' : record.prompt,
    model: record.model,
    status: record.status,
    phase: record.phase,
    createdAt: record.created_at,
    deployedUrl: record.deployed_url,
  };
}

