                    return null as T;
                  }
                  return {
                    deployment_id: 'dep_existing',
                    request_payload_sha256:
                      '2a295a444bcfa6f22ad5f8dfab6ec779be2f4ee84f128928a2784325efce93ae',
                    expires_at: '2999-01-01T00:00:00.000Z',
