          return {
            bind() {
              return {
                async first<T>() {
                  if (!options?.reuseRetryScheduled) {
                    return null as T;
                  }
                  return {
                    deployment_id: 'dep_existing',
                    request_payload_sha256:
                      'bc5770f66f82be23817aea1c4cd23537cec28a833dc39e77ce75f6bf2dcb26cf',
                    expires_at: '2999-01-01T00:00:00.000Z',
                  } as T;
                },
              };
            },
          };
        }

