        if (/SELECT \* FROM workspace_deployments WHERE id = \? AND workspace_id = \?/i.test(sql)) {
          return {
            bind(deploymentId: string) {
              return {
                async first<T>() {
                  if (!state.deploymentExists && !(options?.reuseRetryScheduled && deploymentId === 'dep_existing')) {
