    },
    WORKSPACE_ARTIFACTS: {
      async put() {
        return;
      },
    },
    Sandbox: {
      idFromName() {
        return {};
      },
    },
  };

  return { env, state };
}

export async function runWorkspaceDeploymentRunnerTests(): Promise<void> {
