          return { stdout: '', stderr: '', exitCode: 0 };
        }
        if (command.includes('nimbus_detect_scripts')) {
          return { stdout: JSON.stringify({ hasBuild: false, hasTest: false }), stderr: '', exitCode: 0 };
        }
        if (command.includes('nimbus_detect_secrets')) {
