  }
  if (workspace.status !== 'ready') {
    return jsonResponse(
      {
        error: 'Workspace is not ready',
        workspace: {
          id: workspace.id,
          status: workspace.status,
          errorCode: workspace.errorCode,
          errorMessage: workspace.errorMessage,
